import React, { useMemo } from "react";
import AnomalyChart from "./AnomalyChart";

function frameFilename(idx) {
  const s = String(idx).padStart(6, "0");
  return `frame_${s}.jpg`;
}

export default function Results({ result, videoUrl, backendBase }) {
  const tamperedCount = result?.tampered_frames?.length || 0;
  const totalFrames = result?.total_frames || 0;
  const fps = result?.fps || 25;
  const percent = totalFrames ? ((tamperedCount / totalFrames) * 100).toFixed(2) : "0.00";

  const downloadUrl = backendBase + (result?.artifacts?.download_url || "");
  const annotatedVideoUrl = backendBase + (result?.artifacts?.annotated_video_url || "");
  const framesBaseUrl = backendBase + (result?.artifacts?.frames_base_url || "");

  const previewFrames = useMemo(() => (result?.tampered_frames || []).slice(0, 12), [result]);

  return (
    <div>
      <div style={styles.grid}>
        <div style={styles.panel}>
          <h3 style={styles.h3}>Input Video</h3>
          {videoUrl ? <video src={videoUrl} controls style={styles.video} /> : <div style={styles.muted}>No video</div>}
        </div>

        <div style={styles.panel}>
          <h3 style={styles.h3}>Decision</h3>
          <div style={styles.badge(result.is_tampered)}>{result.is_tampered ? "TAMPERED" : "NOT TAMPERED"}</div>
          <div style={{ marginTop: 10, color: "#444" }}>
            <div>Total frames: {totalFrames}</div>
            <div>FPS: {fps.toFixed ? fps.toFixed(2) : fps}</div>
            <div>Tampered frames: {tamperedCount} ({percent}%)</div>
          </div>
          <div style={{ marginTop: 12, display: "flex", gap: 10, flexWrap: "wrap" }}>
            <a href={downloadUrl} style={styles.linkButton} target="_blank" rel="noreferrer">
              Download artifacts (ZIP)
            </a>
            <a href={annotatedVideoUrl} style={styles.linkButtonAlt} target="_blank" rel="noreferrer">
              View annotated video
            </a>
          </div>
        </div>
      </div>

      <div style={styles.panel}>
        <h3 style={styles.h3}>Anomaly Score vs Frame</h3>
        <AnomalyChart anomalyScores={result.graph_data || []} tamperedFrames={result.tampered_frames || []} />
        <div style={{ marginTop: 10, color: "#555" }}>
          Red points indicate detected tampering. (Frame deletion spikes + interpolation smoothness are both included.)
        </div>
      </div>

      <div style={styles.grid}>
        <div style={styles.panel}>
          <h3 style={styles.h3}>Tampered Timestamps</h3>
          {result.tampered_timestamps?.length ? (
            <ul style={{ marginTop: 8 }}>
              {result.tampered_timestamps.map((t) => (
                <li key={t} style={{ marginBottom: 6 }}>
                  {t}
                </li>
              ))}
            </ul>
          ) : (
            <div style={styles.muted}>No tampering intervals found</div>
          )}
        </div>

        <div style={styles.panel}>
          <h3 style={styles.h3}>Highlighted Frames (preview)</h3>
          {previewFrames.length ? (
            <div style={styles.thumbGrid}>
              {previewFrames.map((idx) => {
                const url = `${framesBaseUrl}/${frameFilename(idx)}`;
                return (
                  <a key={idx} href={url} target="_blank" rel="noreferrer" style={styles.thumbWrap}>
                    <img alt={`frame ${idx}`} src={url} style={styles.thumb} />
                    <div style={styles.thumbLabel}>#{idx}</div>
                  </a>
                );
              })}
            </div>
          ) : (
            <div style={styles.muted}>No highlighted frames saved</div>
          )}
        </div>
      </div>
    </div>
  );
}

const styles = {
  grid: {
    display: "grid",
    gridTemplateColumns: "1.2fr 0.8fr",
    gap: 12,
  },
  panel: {
    border: "1px solid #eee",
    borderRadius: 12,
    padding: 12,
    background: "#fafafa",
  },
  h3: { margin: "4px 0 10px 0" },
  video: { width: "100%", borderRadius: 10, background: "#000" },
  muted: { color: "#666" },
  badge: (isBad) => ({
    display: "inline-block",
    padding: "6px 10px",
    borderRadius: 999,
    fontWeight: 700,
    color: isBad ? "#7f1d1d" : "#0f5132",
    background: isBad ? "#fee2e2" : "#d1fae5",
    border: `1px solid ${isBad ? "#fecaca" : "#a7f3d0"}`,
  }),
  linkButton: {
    display: "inline-block",
    padding: "10px 12px",
    borderRadius: 10,
    background: "#0b5fff",
    color: "white",
    textDecoration: "none",
    fontWeight: 600,
  },
  linkButtonAlt: {
    display: "inline-block",
    padding: "10px 12px",
    borderRadius: 10,
    background: "#111827",
    color: "white",
    textDecoration: "none",
    fontWeight: 600,
  },
  thumbGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(3, minmax(0, 1fr))",
    gap: 10,
  },
  thumbWrap: {
    display: "block",
    textDecoration: "none",
    color: "inherit",
  },
  thumb: {
    width: "100%",
    borderRadius: 10,
    border: "1px solid #eee",
    background: "#000",
  },
  thumbLabel: {
    fontSize: 12,
    marginTop: 4,
    color: "#444",
  },
};
